import { defineQuery } from "next-sanity"

export const PROJECTS_QUERY = defineQuery(`
  *[_type == "project"] | order(order asc, _createdAt desc) {
    _id,
    title,
    "slug": slug.current,
    date,
    description,
    tags,
    "category": category->title,
    coverImage {
      asset->{ _id, url },
      alt,
      hotspot,
      crop
    },
    gallery[] {
      _key,
      mediaType,
      caption,
      image {
        asset->{ _id, url },
        alt,
        hotspot,
        crop
      },
      video {
        asset->{ _id, url, mimeType }
      }
    }
  }
`)
