import { client } from "@/sanity/client"
import { PROJECTS_QUERY } from "@/sanity/queries"
import { urlFor } from "@/sanity/image"
import type { Project, ProjectMedia } from "@/lib/projects"
import { projects as fallbackProjects } from "@/lib/projects"

type SanityProject = {
  _id: string
  title: string
  slug: string
  date: string
  description: string
  tags?: string[]
  category?: string
  coverImage?: {
    asset?: { url?: string }
    alt?: string
  }
  gallery?: Array<{
    _key: string
    mediaType: "image" | "video"
    caption?: string
    image?: {
      asset?: { url?: string }
      alt?: string
    }
    video?: {
      asset?: { url?: string; mimeType?: string }
    }
  }>
}

function mapGalleryItem(item: NonNullable<SanityProject["gallery"]>[number]): ProjectMedia | null {
  if (item.mediaType === "video" && item.video?.asset?.url) {
    return {
      _key: item._key,
      type: "video",
      url: item.video.asset.url,
      caption: item.caption,
    }
  }

  if (item.mediaType === "image" && item.image?.asset) {
    return {
      _key: item._key,
      type: "image",
      url: urlFor(item.image).width(1600).url(),
      alt: item.image.alt,
      caption: item.caption,
    }
  }

  return null
}

function mapSanityProject(project: SanityProject): Project {
  const coverUrl = project.coverImage?.asset
    ? urlFor(project.coverImage).width(1200).height(1200).fit("crop").url()
    : "/placeholder.svg"

  const gallery =
    project.gallery
      ?.map(mapGalleryItem)
      .filter((item): item is ProjectMedia => item !== null) ?? []

  return {
    id: project.slug || project._id,
    title: project.title,
    category: project.category ?? "Otro",
    tags: project.tags ?? [],
    date: project.date,
    image: coverUrl,
    description: project.description,
    gallery,
  }
}

export async function getProjects(): Promise<Project[]> {
  try {
    const data = await client.fetch<SanityProject[]>(PROJECTS_QUERY)
    if (!data?.length) return fallbackProjects
    return data.map(mapSanityProject)
  } catch {
    return fallbackProjects
  }
}
